ALTER TABLE "image_brief" ADD CONSTRAINT "ck_image_brief_operator_direction_bounds" CHECK ("image_brief"."operator_direction" is null or (char_length("image_brief"."operator_direction") <= 1000 and octet_length("image_brief"."operator_direction") <= 4000 and "image_brief"."operator_direction" !~ '[\x00-\x08\x0B-\x1F\x7F-\x9F]' and "image_brief"."operator_direction" !~ '[؜‎‏‪-‮⁦-⁩]'));